import{_ as o,o as c,c as n,a5 as t}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Task — G3 Agency / Workspace (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g3-agency-workspace/task.md","filePath":"mobile/features/g3-agency-workspace/task.md"}'),i={name:"mobile/features/g3-agency-workspace/task.md"};function a(r,e,d,s,l,g){return c(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="task-—-g3-agency-workspace-mobile" tabindex="-1">Task — G3 Agency / Workspace (Mobile) <a class="header-anchor" href="#task-—-g3-agency-workspace-mobile" aria-label="Permalink to &quot;Task — G3 Agency / Workspace (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a></p><p><strong>Trạng thái: ĐÃ CODE XONG (2026-10-23)</strong> — backend + mobile, bao gồm TanStack Query refactor và ClientProfile picker (xem mục cuối). Code thật tại <code>brandhub-mobile-app/src/{screens/agency,screens/workspace,services,store,navigation}</code>.</p><h2 id="infra-state" tabindex="-1">Infra / state <a class="header-anchor" href="#infra-state" aria-label="Permalink to &quot;Infra / state&quot;">​</a></h2><ul><li>[x] <code>useWorkspaceStore</code> (Zustand, <code>src/store/workspaceStore.ts</code>) — <code>currentWorkspace</code>, <code>currentMemberRole</code> (derive từ <code>myRole</code>), <code>currentAgencyId</code> (derive từ <code>agencyId</code>), <code>setCurrentWorkspace()</code>, <code>reset()</code>, <code>switchWorkspace()</code>.</li><li>[x] Persist <code>currentWorkspace.id</code> (không persist cả object) vào <code>expo-secure-store</code> — <code>restore()</code> fetch lại <code>GET /workspaces/{id}</code> khi app mở lại (gọi trong <code>AppNavigator</code> sau <code>authStore.bootstrap()</code>).</li><li>[x] Clear store khi logout — <code>authStore.clearAuth()</code> gọi <code>useWorkspaceStore.getState().reset()</code> đồng bộ.</li><li>[x] TanStack Query key structure (<code>src/services/queryKeys.ts</code>) — <code>agencies.list()</code>, <code>agencies.detail(id)</code>, <code>agencies.stats(id)</code>, <code>agencies.members(id)</code>, <code>agencies.memberProfile(agencyId,userId)</code>, <code>agencies.invitations(id)</code>, <code>agencies.myPendingInvitations()</code>, <code>workspaces.list()</code>, <code>workspaces.detail(id)</code>, <code>workspaces.members(id)</code>, <code>workspaces.myManaged()</code>. Toàn bộ 11 screen G3 dùng <code>useQuery</code>/<code>useMutation</code>, invalidate đúng key sau mỗi mutation (invite/remove/update role/accept/decline). Accept invitation invalidate thêm <code>workspaces.list()</code> để Picker/Switcher không stale.</li></ul><h2 id="agency-screens" tabindex="-1">Agency screens <a class="header-anchor" href="#agency-screens" aria-label="Permalink to &quot;Agency screens&quot;">​</a></h2><ul><li>[x] Agency List (FR 3.4.1) — <code>AgencyListScreen.tsx</code>, <code>GET /agencies</code>, truy cập từ Settings → &quot;Agency của tôi&quot;.</li><li>[x] Agency Dashboard (FR 3.4.2) — gộp vào <code>AgencyDetailScreen.tsx</code>, <code>GET /agencies/{id}/stats</code> (memberCount/workspaceCount).</li><li>[x] Agency Profile (FR 3.4.4) — <code>AgencyDetailScreen.tsx</code>, <code>GET /agencies/{id}</code>.</li><li>[x] Agency Member List (<code>AgencyMembersScreen.tsx</code>) + Member Profile drawer (<code>MemberProfileScreen.tsx</code>) — info cơ bản (fullName/email/phone/professionalTitle) + list workspace+role. Activity Feed (<code>AuditLogResponse</code>) <strong>cắt ở bản này</strong> theo đúng gợi ý task.md gốc.</li><li>[x] Invite Agency Member modal (FR 3.4.7) — <code>AgencyInviteScreen.tsx</code>, <code>POST /agencies/{id}/invitations</code>, OWNER only.</li><li>[x] Pending Invitations screen — <code>AgencyInvitationsScreen.tsx</code> (phía Owner, <code>GET /agencies/{id}/invitations</code> + revoke) và <code>MyInvitationsScreen.tsx</code> (phía được mời, <code>GET /agencies/invitations/my-pending</code>, Accept/Decline).</li></ul><h2 id="workspace-screens" tabindex="-1">Workspace screens <a class="header-anchor" href="#workspace-screens" aria-label="Permalink to &quot;Workspace screens&quot;">​</a></h2><ul><li>[x] Workspace List theo Agency (FR 3.4.10) — <code>WorkspacePickerScreen.tsx</code>, <code>GET /workspaces</code>.</li><li>[x] Workspace Detail — <code>WorkspaceDetailScreen.tsx</code> (FR 3.4.13). <code>timezoneConfig</code> <strong>đã thêm vào <code>WorkspaceResponse</code></strong> (backend fix, xem mục Bug đã sửa).</li><li>[x] Tab Members (FR 3.4.18) — <code>WorkspaceMembersScreen.tsx</code>, <code>GET /workspaces/{id}/members</code>, role badge.</li><li>[x] Invite/Assign Member modal (FR 3.4.19) — <code>WorkspaceInviteMemberScreen.tsx</code>, chỉ hiện nếu <code>currentMemberRole === MANAGER</code>; chặn UI nếu email chưa là Agency Member (check client-side qua <code>agencyService.listMembers</code>, hiện hint &quot;mời vào Agency trước&quot; thay vì gọi API nhận lỗi 409).</li><li>[x] Update Member Role (FR 3.4.20) + Remove Member (FR 3.4.21) — long-press trong <code>WorkspaceMembersScreen.tsx</code>, MANAGER only.</li><li>[x] Leave Workspace (FR 3.4.16) — nút ở <code>WorkspaceDetailScreen.tsx</code>, ẩn với OWNER.</li><li>[x] Workspace Switcher — <code>SettingsScreen.tsx</code> nút &quot;Đổi Workspace&quot; (<code>switchWorkspace()</code> → quay lại <code>WorkspacePickerScreen</code>). Shortcut &quot;My Managed Workspaces&quot; — <code>ManagedWorkspacesScreen.tsx</code>, <code>GET /workspaces/my-managed</code>.</li></ul><h2 id="business-rules-đa-enforce-o-client" tabindex="-1">Business rules đã enforce ở client <a class="header-anchor" href="#business-rules-đa-enforce-o-client" aria-label="Permalink to &quot;Business rules đã enforce ở client&quot;">​</a></h2><ul><li>[x] Không cache 1 &quot;role&quot; duy nhất per-user toàn app — luôn đọc <code>currentMemberRole</code> từ <code>workspaceStore</code> (derive theo <code>currentWorkspace.myRole</code> mỗi lần set).</li><li>[x] UI phân biệt 2 tầng permission: Agency-level (<code>ownerId</code>, check qua <code>agency.myRole === &quot;OWNER&quot;</code>) vs Workspace-level (<code>currentMemberRole</code> MANAGER/CREATOR/CLIENT).</li><li>[x] Hiển thị đúng status invitation (Pending/Accepted/Rejected/Expired) qua <code>STATUS_LABEL</code> map trong <code>AgencyInvitationsScreen</code>/<code>MyInvitationsScreen</code> — hết hạn tự động phía BE, mobile chỉ đọc field <code>status</code> trả về, không tự tính.</li><li>[x] Remove Agency/Workspace Member — không có cảnh báo mất dữ liệu (đúng theo rule, tài nguyên họ tạo không bị xoá theo).</li></ul><h2 id="chua-lam-out-of-scope-g3-xem-spec-muc-7" tabindex="-1">Chưa làm / out of scope G3 (xem spec mục 7) <a class="header-anchor" href="#chua-lam-out-of-scope-g3-xem-spec-muc-7" aria-label="Permalink to &quot;Chưa làm / out of scope G3 (xem spec mục 7)&quot;">​</a></h2><ul><li>[ ] Không làm: Create/Update/Remove Agency, Create/Update/Delete Workspace, Save Workspace Template, Billing/Subscription Workspace, Duplicate Workspace, Workspace Settings update (logo/banner).</li><li>[ ] Activity Feed trong Member Profile drawer (<code>AuditLogResponse</code>) — cắt khỏi bản đầu, API <code>/members/{userId}/activity</code> đã có sẵn, chưa code UI.</li></ul><h2 id="bug-backend-đa-phat-hien-sua-trong-luc-code-2026-10-23" tabindex="-1">Bug backend đã phát hiện + sửa trong lúc code (2026-10-23) <a class="header-anchor" href="#bug-backend-đa-phat-hien-sua-trong-luc-code-2026-10-23" aria-label="Permalink to &quot;Bug backend đã phát hiện + sửa trong lúc code (2026-10-23)&quot;">​</a></h2><ol><li><strong><code>timezoneConfig</code> thiếu trong <code>WorkspaceResponse</code></strong> — không phải thiết kế thiếu, chỉ thiếu wiring 1 dòng (<code>Workspace.getTimezoneConfig()</code> có sẵn, DTO record quên thêm field). Đã sửa <code>WorkspaceResponse.java</code> + 2 call site (<code>WorkspaceServiceImpl.toResponse()</code>, <code>WorkspaceTemplateServiceImpl</code>).</li><li><strong>Agency Owner xem Workspace bị 403 — dead code thật</strong>: <code>WorkspaceServiceImpl.getWorkspace()</code> có logic gán <code>myRole = &quot;OWNER&quot;</code> cho Agency Owner (dòng ~205-210) nhưng <strong>không bao giờ chạy tới</strong> vì <code>assertMember()</code> throw <code>WORKSPACE_ACCESS_DENIED</code> trước đó — <code>assertMember</code> không hề check Agency Owner. Thêm nữa, <code>@RequireRole({MANAGER, CREATOR, CLIENT})</code> ở <code>WorkspaceController</code> (3 endpoint: <code>getWorkspace</code>, <code>getDashboard</code>, <code>listMembers</code>) thiếu <code>MemberRole.OWNER</code> trong list allowed, nên fallback Owner có sẵn trong <code>RequireRoleAspect</code> (dòng 86-93, check <code>allowed.contains(MemberRole.OWNER)</code>) cũng không bao giờ kích hoạt. Đã sửa cả annotation (thêm <code>OWNER</code>) và <code>assertMember()</code> (thêm check Agency Owner) ở cả 3 endpoint.</li></ol><h2 id="clientprofile-picker-cho-client-accept-invitation-bo-sung-2026-10-23" tabindex="-1">ClientProfile picker cho CLIENT accept invitation (bổ sung 2026-10-23) <a class="header-anchor" href="#clientprofile-picker-cho-client-accept-invitation-bo-sung-2026-10-23" aria-label="Permalink to &quot;ClientProfile picker cho CLIENT accept invitation (bổ sung 2026-10-23)&quot;">​</a></h2><p>Ban đầu chặn: CLIENT role cần chọn/tạo <code>ClientProfile</code> lúc accept invitation (field <code>clientProfileId</code> hoặc <code>newClientProfile</code> trong <code>AcceptInvitationRequest</code>), mobile chưa có UI nên yêu cầu dùng web. Đã bổ sung đầy đủ:</p><ul><li><code>AcceptInvitationScreen.tsx</code> — khi <code>invitation.role === &quot;CLIENT&quot;</code>, hiện picker chọn 1 trong <code>myClientProfiles</code> có sẵn, hoặc form tạo mới (<code>displayName</code> bắt buộc, <code>company</code>/<code>phone</code> tùy chọn — đúng theo <code>ClientProfileRequest</code>, không thêm field khác).</li><li><code>MyInvitationsScreen.tsx</code> — nút &quot;Nhận&quot; với invitation CLIENT navigate sang <code>AcceptInvitationScreen</code> (dùng chung picker, không duplicate UI).</li><li>Sửa luôn 1 type-mismatch: <code>agencyService.ts</code> khai <code>InvitationPreview.myClientProfiles: {id, name}[]</code> sai field — backend trả <code>ClientProfileResponse</code> thật có field <code>displayName</code>, không có <code>name</code>.</li></ul><p><strong>Kết quả: CLIENT giờ accept/decline invitation hoàn toàn trên mobile, không cần mở web.</strong> Sau khi đã là member của workspace (bất kể role), mọi tính năng khác (G1 auth, G2 upload, G3 workspace/agency view) hoạt động bình thường như MANAGER/CREATOR — không có giới hạn nào khác ngoài bước accept lần đầu này.</p><h2 id="rui-ro-con-mo-khong-block-hoi-team-sau" tabindex="-1">Rủi ro còn mở (không block, hỏi team sau) <a class="header-anchor" href="#rui-ro-con-mo-khong-block-hoi-team-sau" aria-label="Permalink to &quot;Rủi ro còn mở (không block, hỏi team sau)&quot;">​</a></h2><ol><li>Deep-link <code>brandhub://invite?token=...</code> — đã config <code>scheme</code> trong <code>app.json</code> + <code>linking</code> trong <code>AppNavigator</code>, nhưng <strong>backend <code>MailServiceImpl</code> hiện chỉ build link web</strong> (<code>frontendUrl/invitations/accept?token=</code>) trong email mời, chưa có link <code>brandhub://</code>. Cần team xác nhận có bổ sung mobile deep-link trong email không, nếu không thì luồng &quot;mở link từ email → vào thẳng app&quot; chưa hoạt động thật (chỉ <code>MyInvitationsScreen</code> trong app hoạt động được).</li><li>Deep-link accept chỉ resolve được khi app đang ở <code>MainTabNavigator</code> (đã login + đã chọn workspace) — nếu mở link lúc chưa login, route không khớp và bị bỏ qua lặng lẽ.</li></ol>',21)])])}const u=o(i,[["render",a]]);export{p as __pageData,u as default};
